# Custom REST Service in Dynamics AX (D365 F&O) using X++

## Overview
This guide demonstrates how to create a custom REST service in Dynamics 365 Finance & Operations using X++.

---

## Step 1: Create a Data Contract Class

```xpp
/// <summary>
/// Data contract class for Customer Service
/// </summary>
[DataContractAttribute]
public class CustomerServiceContract
{
    private str     custAccount;
    private str     custName;
    private str     custGroup;
    private str     currency;
    private boolean isActive;

    /// <summary>
    /// Customer Account
    /// </summary>
    [DataMemberAttribute('CustAccount')]
    public str parmCustAccount(str _custAccount = custAccount)
    {
        custAccount = _custAccount;
        return custAccount;
    }

    /// <summary>
    /// Customer Name
    /// </summary>
    [DataMemberAttribute('CustName')]
    public str parmCustName(str _custName = custName)
    {
        custName = _custName;
        return custName;
    }

    /// <summary>
    /// Customer Group
    /// </summary>
    [DataMemberAttribute('CustGroup')]
    public str parmCustGroup(str _custGroup = custGroup)
    {
        custGroup = _custGroup;
        return custGroup;
    }

    /// <summary>
    /// Currency Code
    /// </summary>
    [DataMemberAttribute('Currency')]
    public str parmCurrency(str _currency = currency)
    {
        currency = _currency;
        return currency;
    }

    /// <summary>
    /// Is Active Flag
    /// </summary>
    [DataMemberAttribute('IsActive')]
    public boolean parmIsActive(boolean _isActive = isActive)
    {
        isActive = _isActive;
        return isActive;
    }
}
```

---

## Step 2: Create a Response Contract Class

```xpp
/// <summary>
/// Response contract class for Customer Service
/// </summary>
[DataContractAttribute]
public class CustomerServiceResponse
{
    private str     responseCode;
    private str     responseMessage;
    private str     custAccount;
    private boolean success;

    [DataMemberAttribute('ResponseCode')]
    public str parmResponseCode(str _responseCode = responseCode)
