        return responseCode;
    }

    [DataMemberAttribute('ResponseMessage')]
    public str parmResponseMessage(str _responseMessage = responseMessage)
    {
        responseMessage = _responseMessage;
        return responseMessage;
    }

    [DataMemberAttribute('CustAccount')]
    public str parmCustAccount(str _custAccount = custAccount)
    {
        custAccount = _custAccount;
        return custAccount;
    }

    [DataMemberAttribute('Success')]
    public boolean parmSuccess(boolean _success = success)
    {
        success = _success;
        return success;
    }
}
```

---

## Step 3: Create a List Response Contract

```xpp
/// <summary>
/// List Response contract for returning multiple customers
/// </summary>
[DataContractAttribute]
public class CustomerListResponse
{
    private List        customerList;
    private int         totalCount;
    private str         responseMessage;

    [DataMemberAttribute('CustomerList'),
     AifCollectionTypeAttribute('CustomerList', Types::Class, classStr(CustomerServiceContract))]
    public List parmCustomerList(List _customerList = customerList)
    {
        customerList = _customerList;
        return customerList;
    }

    [DataMemberAttribute('TotalCount')]
    public int parmTotalCount(int _totalCount = totalCount)
    {
        totalCount = _totalCount;
        return totalCount;
    }

    [DataMemberAttribute('ResponseMessage')]
    public str parmResponseMessage(str _responseMessage = responseMessage)
    {
        responseMessage = _responseMessage;
        return responseMessage;
    }
}
```

---

## Step 4: Create the Service Class

```xpp
/// <summary>
/// Custom Customer REST Service Class
/// </summary>
public class CustomerRESTService
{
    /// <summary>
    /// Get Customer by Account Number
    /// </summary>
    /// <param name="_custAccount">Customer Account Number</param>
    /// <returns>CustomerServiceContract</returns>
    public CustomerServiceContract getCustomer(str _custAccount)
    {
        CustomerServiceContract response = new CustomerServiceContract();
        CustTable               custTable;

        try
        {
            custTable = CustTable::find(_custAccount);

            if (custTable.RecId != 0)
            {
                response.parmCustAccount(custTable.AccountNum);
                response.parmCustName(custTable.name());
                response.parmCustGroup(custTable.CustGroup);
                response.parmCurrency(custTable.Currency);
                response.parmIsActive(custTable.Blocked == CustVendorBlocked::No);
            }
            else
            {
                throw error(strFmt("Customer %1 not found.", _custAccount));
            }
        }
        catch (Exception::Error)
        {
            throw error("An error occurred while retrieving the customer.");
        }

        return response;
    }

    /// <summary>
    /// Get All Customers with optional filter
    /// </summary>
    /// <param name="_custGroup">Customer Group Filter (optional)</param>
    /// <returns>CustomerListResponse</returns>
    public CustomerListResponse getAllCustomers(str _custGroup = "")
    {
        CustomerListResponse    listResponse    = new CustomerListResponse();
        CustomerServiceContract contract;
        CustTable               custTable;
        List                    customerList    = new List(Types::Class);
        int                     count           = 0;

        try
        {
            while select custTable
                where (_custGroup == "" || custTable.CustGroup == _custGroup)
            {
                contract = new CustomerServiceContract();
                contract.parmCustAccount(custTable.AccountNum);
                contract.parmCustName(custTable.name());
                contract.parmCustGroup(custTable.CustGroup);
                contract.parmCurrency(custTable.Currency);
                contract.parmIsActive(custTable.Blocked == CustVendorBlocked::No);

                customerList.addEnd(contract);
                count++;
            }

            listResponse.parmCustomerList(customerList);
            listResponse.parmTotalCount(count);
            listResponse.parmResponseMessage(strFmt("Successfully retrieved %1 customers.", count));
        }
        catch (Exception::Error)
        {
            throw error("An error occurred while retrieving customers.");
        }

        return listResponse;
    }

    /// <summary>
    /// Create a New Customer
    /// </summary>
    /// <param name="_contract">CustomerServiceContract</param>
    /// <returns>CustomerServiceResponse</returns>
    public CustomerServiceResponse createCustomer(CustomerServiceContract _contract)
    {
        CustomerServiceResponse response    = new CustomerServiceResponse();
        CustTable               custTable;
        NumberSeq               numberSeq;

        try
        {
            // Validate input
            if (!_contract.parmCustGroup())
            {
                throw error("Customer Group is required.");
            }

            if (!_contract.parmCurrency())
            {
                throw error("Currency is required.");
            }

            ttsbegin;

            // Generate Account Number
            numberSeq = NumberSeq::newGetNum(
                CustParameters::numRefCustAccount()
            );

            custTable.clear();
            custTable.AccountNum    = numberSeq.num();
            custTable.CustGroup     = _contract.parmCustGroup();
            custTable.Currency      = _contract.parmCurrency();

            // Set Name via DirPartyTable
            custTable.initValue();
            custTable.insert();

            // Update Party Name
            DirParty dirParty = DirParty::constructFromCommon(custTable);
            DirPartyName partyName;
            partyName.Name = _contract.parmCustName();
            dirParty.createOrUpdateName(partyName);

            ttscommit;

            response.parmSuccess(true);
            response.parmResponseCode("200");
            response.parmResponseMessage("Customer created successfully.");
            response.parmCustAccount(custTable.AccountNum);
        }
        catch (Exception::Error)
        {
            ttsabort;
            response.parmSuccess(false);
            response.parmResponseCode("500");
            response.parmResponseMessage("Error creating customer: " + infolog.text());
        }

        return response;
    }

    /// <summary>
    /// Update an existing Customer
    /// </summary>
    /// <param name="_contract">CustomerServiceContract</param>
    /// <returns>CustomerServiceResponse</returns>
    public CustomerServiceResponse updateCustomer(CustomerServiceContract _contract)
    {
        CustomerServiceResponse response = new CustomerServiceResponse();
        CustTable               custTable;

        try
        {
            custTable = CustTable::find(_contract.parmCustAccount(), true);

            if (custTable.RecId == 0)
            {
                response.parmSuccess(false);
                response.parmResponseCode("404");
                response.parmResponseMessage(
                    strFmt("Customer %1 not found.", _contract.parmCustAccount())
                );
                return response;
            }

            ttsbegin;

            if (_contract.parmCustGroup())
            {
                custTable.CustGroup = _contract.parmCustGroup();
            }

            if (_contract.parmCurrency())
            {
                custTable.Currency = _contract.parmCurrency();
            }

            custTable.update();

            ttscommit;

            response.parmSuccess(true);
            response.parmResponseCode("200");
            response.parmResponseMessage("Customer updated successfully.");
            response.parmCustAccount(custTable.AccountNum);
        }
        catch (Exception::Error)
        {
            ttsabort;
            response.parmSuccess(false);
            response.parmResponseCode("500");
            response.parmResponseMessage("Error updating customer: " + infolog.text());
        }

        return response;
    }

    /// <summary>
    /// Delete a Customer
    /// </summary>
    /// <param name="_custAccount">Customer Account Number</param>
    /// <returns>CustomerServiceResponse</returns>
    public CustomerServiceResponse deleteCustomer(str _custAccount)
    {
        CustomerServiceResponse response = new CustomerServiceResponse();
        CustTable               custTable;

        try
        {
            custTable = CustTable::find(_custAccount, true);

            if (custTable.RecId == 0)
            {
                response.parmSuccess(false);
                response.parmResponseCode("404");
                response.parmResponseMessage(
                    strFmt("Customer %1 not found.", _custAccount)
                );
                return response;
            }

            ttsbegin;
            custTable.delete();
            ttscommit;

            response.parmSuccess(true);
            response.parmResponseCode("200");
            response.parmResponseMessage(
                strFmt("Customer %1 deleted successfully.", _custAccount)
            );
        }
        catch (Exception::Error)
        {
            ttsabort;
            response.parmSuccess(false);
            response.parmResponseCode("500");
            response.parmResponseMessage("Error deleting customer: " + infolog.text());
        }

        return response;
    }
}
```

